                    "sql": "Create or replace Table DANIEL_KLEIN_DB.MAPLEMONK.DANIEL_KLEIN_DB_UNICOMMERCE_FACT_ITEMS AS SELECT * FROM ( SELECT \"Shipping Address Pincode\" AS shipping_pincode, \"Billing Address Pincode\" AS billing_pincode, \"Channel Name\" AS marketplace, \"Channel Name\" AS source, \"Display Order Code\" AS order_id, \"Display Order Code\" AS reference_code, \"Shipping Address Phone\" AS phone, \"Billing Address Name\" AS name, \"Notification Email\" AS email, UPPER(category) AS category, TO_VARCHAR(TRY_TO_TIMESTAMP(NULLIF(UPDATED, \'\')), \'YYYY-MM-DD\"T\"HH24:MI:SS\') AS SHIPPING_LAST_UPDATE_DATE, \"Shipping provider\" AS Shipping_Provider, \"Item SKU Code\" AS sku, \"Seller SKU Code\" AS Marketplace_sku, case when upper(marketplace) like \'%PHARMEASY%\' then LTRIM(\"Channel Product Id\", \'0\') else \"Channel Product Id\" end AS product_id, COALESCE(\"Item Type Name\", \"SKU Name\") AS product_name, CURRENCY, COALESCE(\"Shipping Address City\", \"Billing Address City\") AS city, COALESCE(\"Shipping Address State\", \"Billing Address State\") AS state, CASE WHEN \"Sale Order Status\" NOT IN (\'COMPLETE\',\'CANCELLED\') AND \"Shipping Package Status Code\" IS NULL THEN \'UNFULFILLABLE\' ELSE \"Sale Order Status\" END AS order_status, \"Invoice Code\" AS invoice_code, TO_VARCHAR(TRY_TO_TIMESTAMP(NULLIF(\"Invoice Created\", \'\')), \'YYYY-MM-DD\"T\"HH24:MI:SS\') AS invoice_date, TO_VARCHAR(TRY_TO_TIMESTAMP(NULLIF(\"Order Date as dd/mm/yyyy hh:MM:ss\", \'\')), \'YYYY-MM-DD\"T\"HH24:MI:SS\') AS order_date, TO_VARCHAR(TRY_TO_TIMESTAMP(NULLIF(\"Shipping Package Creation Date\", \'\')), \'YYYY-MM-DD\"T\"HH24:MI:SS\') AS shipping_package_creation_date, TRY_TO_DOUBLE(\"Shipping Charges\") AS shipping_price, 1 AS suborder_quantity, TRY_TO_DOUBLE(discount) AS discount, TRY_TO_DOUBLE(\"Tax Value\") AS tax, CASE WHEN UPPER(\"Source Code\") IN (\'MYNTRAPPMP\', \'SHOPIFY\') THEN TRY_TO_DOUBLE(\"Selling Price\") ELSE TRY_TO_DOUBLE(\"Selling Price\") + COALESCE(TRY_TO_DOUBLE(discount), 0) END AS selling_price, \"Shipping Package Code\" AS shippingPackageCode, \"Shipping Package Status Code\" AS shippingPackageStatus, \"Sale Order Item Code\" AS SaleOrderItemCode, \"Sale Order Item Code\" AS Sales_Order_Item_ID, \"Tracking Number\" AS AWB, FACILITY AS Warehouse_Name, CASE WHEN COD = \'0\' THEN \'Prepaid\' ELSE \'COD\' END AS Payment_Mode, CASE WHEN COD = \'0\' THEN \'Prepaid\' ELSE \'COD\' END AS Payment_Method, \"Shipping Courier\" AS Courier, \"Shipping Courier Status\" AS shipping_status, \"Shipping Tracking Status\" AS shipping_tracking_status, 1 AS shippedQuantity, TO_VARCHAR(TRY_TO_TIMESTAMP(NULLIF(\"Dispatch Date\", \'\')), \'YYYY-MM-DD\"T\"HH24:MI:SS\') AS dispatch_date, TO_VARCHAR(TRY_TO_TIMESTAMP(NULLIF(\"EWayBill Date\", \'\')), \'YYYY-MM-DD\"T\"HH24:MI:SS\') AS ewaybill_date, TO_VARCHAR(TRY_TO_TIMESTAMP(NULLIF(\"Delivery Time\", \'\')), \'YYYY-MM-DD\"T\"HH24:MI:SS\') AS delivery_date, TO_VARCHAR(TRY_TO_TIMESTAMP(NULLIF(\"Return Date\", \'\')), \'YYYY-MM-DD\"T\"HH24:MI:SS\') AS return_date, TO_VARCHAR(TRY_TO_TIMESTAMP(NULLIF(\"Reverse Pickup Created Date\", \'\')), \'YYYY-MM-DD\"T\"HH24:MI:SS\') AS reverse_pickup_date, TO_VARCHAR(TRY_TO_TIMESTAMP(NULLIF(\"Fulfillment TAT\", \'\')), \'YYYY-MM-DD\"T\"HH24:MI:SS\') AS fulfillment_tat, \"Reverse Pickup Code\" AS reverse_pickup_code, \"Return Remarks\" AS return_remarks, \"Reverse Pickup Reason\" AS reverse_pickup_reason, CASE WHEN \"Return Date\" IS NOT NULL AND TRIM(\"Return Date\") <> \'\' AND LOWER(TRIM(\"Return Date\")) <> \'null\' THEN 1 ELSE 0 END AS return_flag, CASE WHEN \"Return Date\" IS NOT NULL AND TRIM(\"Return Date\") <> \'\' AND LOWER(TRIM(\"Return Date\")) <> \'null\' THEN 1 ELSE 0 END AS return_quantity, CASE WHEN \"Return Date\" IS NOT NULL AND TRIM(\"Return Date\") <> \'\' AND LOWER(TRIM(\"Return Date\")) <> \'null\' THEN TRY_TO_DOUBLE(\"Selling Price\") ELSE 0 END AS return_sales, CASE WHEN LOWER(\"Sale Order Status\") LIKE \'%cancel%\' OR LOWER(\"Shipping Courier Status\") LIKE \'%cancel%\' THEN 1 ELSE 0 END AS cancelled_quantity, Upper(COALESCE(gs.CATALOG_NAME, fi.\"Item Type Name\")) as mapped_product_name, Upper(COALESCE(gs.PRODUCT_CATEGORY, fi.category)) as mapped_category, Upper(gs.PRODUCT_SUB_CATEGORY) as mapped_sub_category, Upper(COALESCE(gs.master_sku, fi.\"Item SKU Code\")) as commonsku, NULL as cogs, COALESCE(TRY_CAST(gs.MRP as INT), TRY_CAST(fi.mrp as INT)) as sku_mrp, Fi.\"Item Type Brand\" as brand, NULL as tax_rate, NULL as packaging_cost, ROW_NUMBER() OVER ( PARTITION BY \"Display Order Code\", \"Sale Order Item Code\" ORDER BY TRY_TO_TIMESTAMP(NULLIF(updated, \'\')) DESC ) AS rw FROM DANIEL_KLEIN_DB.MAPLEMONK.unicommerce_get_sale_orders fi LEFT JOIN ( SELECT * FROM DANIEL_KLEIN_DB.MAPLEMONK.Google_Sheet_SKU_MASTER QUALIFY ROW_NUMBER() OVER ( PARTITION BY MASTER_SKU ORDER BY MASTER_SKU ) = 1 ) gs ON TRIM(fi.\"Item SKU Code\") = TRIM(gs.MASTER_SKU) ) WHERE rw = 1;",
